for (const locale of localeOrder) {
  if (!copy[locale]) throw new Error(`Missing badge guide copy: ${locale}`);
  if (!grantCopy[locale]) throw new Error(`Missing badge grant copy: ${locale}`);
  if (!copy[locale].groupOrder?.every((group) => copy[locale].groups[group])) throw new Error(`Missing badge guide group copy: ${locale}`);
  if (!copy[locale].mechanics?.paragraphs?.length || !copy[locale].mechanics?.bullets?.length) throw new Error(`Missing badge guide mechanics copy: ${locale}`);
  if (!copy[locale].listNote || !copy[locale].related?.items) throw new Error(`Missing badge guide navigation copy: ${locale}`);
  if (!copy[locale].groupImages?.route || !copy[locale].groupImages?.newMaps) throw new Error(`Missing badge guide group image: ${locale}`);
}

for (const entry of badgeGuideEntries) {
  if (!entry.name || !entry.grantKey || !entry.reward || !localeOrder.every((locale) => entry.condition?.[locale])) throw new Error(`Incomplete badge guide entry: ${entry.name ?? 'unknown'}`);
}

export const badgeGuideCopy = copy;
export const badgeGrantCopy = grantCopy;
export const badgeCardLabels = commonLabels;
